  ('7212f441-4757-4335-86b1-e9f62db7dd7b', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', 'c8d37de4-8e3d-40bb-99db-2d85b2b726b4', 'concept'::public.curated_course_node_type, 'Political criticism without reducing texts to slogans', null, 2),
