  ('7d69005e-0ca5-4d6d-bf8a-bb0ec60ad868', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '41f31db9-bd72-4fd9-b11b-1f9d2350a57f', 'concept'::public.curated_course_node_type, 'Imaginary, Symbolic, Real, mirror stage, objet petit a, lack, and signifying chain', null, 0),
