  ('996ab4c4-1dfd-4f56-842e-bf93d94da9e6', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '953b1a10-5510-4f10-9d90-91bb349e4f13', 'concept'::public.curated_course_node_type, 'Affect, emotion, mood, atmosphere, attachment, shame, optimism, and public feeling', null, 0),
