  ('6ad9ac52-38e9-48c5-9da0-837fed518f32', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '953b1a10-5510-4f10-9d90-91bb349e4f13', 'concept'::public.curated_course_node_type, 'How feeling organizes interpretation and social worlds', null, 2),
