  ('4c05c530-417e-4397-b3ae-df3b0c4b3831', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '57ae4c69-c7f2-4898-a5ff-3c2e5d375d4d', 'concept'::public.curated_course_node_type, 'Body as theme, method, archive, and reading condition', null, 1),
  ('cc29f498-c403-46ce-9a8b-247c07b8ab69', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '57ae4c69-c7f2-4898-a5ff-3c2e5d375d4d', 'concept'::public.curated_course_node_type, 'Ethics of reading bodies, pain, testimony, and difference', null, 2),
