  ('3d5a0684-b515-4566-9fb2-4e942e54456f', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', 'a83af5b2-7c28-4c24-b992-630442d4be5d', 'concept'::public.curated_course_node_type, 'Nature writing, pastoral, wilderness, climate fiction, toxicity, and environmental imagination', null, 0),
  ('b6e6eac1-d9f8-476f-b892-5b18ee795a43', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', 'a83af5b2-7c28-4c24-b992-630442d4be5d', 'concept'::public.curated_course_node_type, 'Buell, Glotfelty, Heise, Garrard, Nixon, and environmental justice criticism', null, 1),
