  ('2773a864-ca81-4960-a92d-b183c36622bb', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '0ae2baeb-c000-4dfe-99a5-ce6cac305d60', 'concept'::public.curated_course_node_type, 'Energy humanities, extractive capitalism, petrofiction, toxicity, waste, sacrifice zones, and climate inequality', null, 0),
