  ('1367aa2d-f839-4a62-b8fa-85f77c17838a', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', 'd03ead6c-63fb-409d-9ce8-6ead9b12b876', 'concept'::public.curated_course_node_type, 'Anthropocene debates, planetary scale, multispecies relations, material ecocriticism, and posthumanism', null, 0),
  ('0f5bab53-8f6f-408e-b64d-e253d94f4bdf', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', 'd03ead6c-63fb-409d-9ce8-6ead9b12b876', 'concept'::public.curated_course_node_type, 'Haraway, Chakrabarty, Latour, Tsing, Iovino, Oppermann, and new materialism', null, 1),
