  ('c745a192-0a52-49ed-810d-b9fa458a6212', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '9885c94e-db34-447b-bd32-35d143efeb19', 'concept'::public.curated_course_node_type, 'Digital archives, databases, metadata, editions, TEI, public humanities, and infrastructure', null, 0),
