  ('993ca63a-f48c-4d6c-9bf9-b17da236029c', 'e9f0a1b2-3c4d-4f38-9b78-8c9d0e1f2a88', '2dab0119-45ca-4a38-b133-91bc3413458e', 'concept'::public.curated_course_node_type, 'Feasible, original, ethical, and evidence-driven design', null, 2),
